package cn.workbench;
import org.springframework.web.bind.annotation.*;import jakarta.servlet.http.HttpServletRequest;import java.util.*;
@RestController @RequestMapping("/api/v1") public class TaskController {
 final TaskService tasks;final Policy policy;final Writes writes;final Records records;final Store db;final WorkItemService workItems;
 public TaskController(TaskService t,Policy p,Writes w,Records r,Store d,WorkItemService workItems){tasks=t;policy=p;writes=w;records=r;db=d;this.workItems=workItems;}
 @GetMapping("/tasks") Object list(HttpServletRequest q,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String status,@RequestParam(required=false)String keyword,@RequestParam(required=false)String priority,@RequestParam(required=false)Boolean overdue){var items=filter(tasks.tasks(policy.actor(q)),status,keyword,priority,overdue);return Api.ok(page(items,page,pageSize));}
 @GetMapping("/tasks/{id}") Object detail(@PathVariable long id,HttpServletRequest q){var a=policy.actor(q);var task=tasks.detail(a,id);task.put("workItems",workItems.forTask(a,task));task.put("workItemDepartments",workItems.manageableDepartments(a,task));return Api.ok(task);}
 @GetMapping("/tasks/{id}/work-item-members") Object workItemMembers(@PathVariable long id,@RequestParam int deptId,HttpServletRequest q){return Api.ok(workItems.members(policy.actor(q),id,deptId));}
 @PostMapping("/tasks/{id}/work-items") Object createWorkItem(@PathVariable long id,@RequestBody Map<String,Object> body,HttpServletRequest q){var a=policy.actor(q);return writes.run(q,body,()->workItems.create(a,id,body));}
 @PostMapping("/work-items/{id}") Object updateWorkItem(@PathVariable long id,@RequestBody Map<String,Object> body,HttpServletRequest q){var a=policy.actor(q);return writes.run(q,body,()->workItems.update(a,id,body));}
 @PostMapping("/tasks") Object create(@RequestBody Map<String,Object>b,HttpServletRequest q){var a=policy.actor(q);return writes.run(q,b,()->tasks.create(a,b));}
 @PostMapping("/tasks/{id}/{action:confirm-assign|accept|reject|cancel|deadline|summarize|urge}") Object action(@PathVariable long id,@PathVariable String action,@RequestBody(required=false)Map<String,Object>body,HttpServletRequest q){var b=body==null?new LinkedHashMap<String,Object>():body;var a=policy.actor(q);return writes.run(q,b,()->tasks.taskAction(a,id,action,b));}
 @GetMapping("/sub-tasks/mine") Object mine(HttpServletRequest q,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String status,@RequestParam(required=false)String keyword,@RequestParam(required=false)String priority,@RequestParam(required=false)Boolean overdue){var a=policy.actor(q);var list=records.list("SUB_TASK",a.company(),a.leader()?null:a.dept()).stream().filter(s->{try{policy.subtask(a,s,false);return true;}catch(ApiException e){return false;}}).map(s->{var c=new LinkedHashMap<>(s);var t=records.get(Jsons.number(s.get("taskId")));c.put("taskTitle",t.get("title"));c.put("title",t.get("title"));c.put("code",t.get("code"));c.put("priority",t.get("priority"));c.put("allowedActions",tasks.subActions(a,t,s));return (Map<String,Object>)c;}).toList();var combined=new ArrayList<Map<String,Object>>(list);combined.addAll(workItems.mine(a));return Api.ok(page(filter(combined,status,keyword,priority,overdue),page,pageSize));}
 static List<Map<String,Object>> filter(List<Map<String,Object>> items,String status,String keyword,String priority,Boolean overdue){String term=keyword==null?"":keyword.trim().toLowerCase(Locale.ROOT);var now=java.time.Instant.now();return items.stream().filter(row->{String state=String.valueOf(row.get("status"));if(status!=null&&!status.isBlank()&&!status.equals(state)&&!(status.equals("IN_PROGRESS")&&state.equals("REWORK"))&&!(status.equals("PENDING_ACCEPTANCE")&&state.equals("PENDING_ACCEPTANCE_WITH_GAP")))return false;if(priority!=null&&!priority.isBlank()&&!priority.equals(row.get("priority")))return false;if(!term.isEmpty()&&!String.valueOf(row.getOrDefault("title","")).toLowerCase(Locale.ROOT).contains(term)&&!String.valueOf(row.getOrDefault("code","")).toLowerCase(Locale.ROOT).contains(term))return false;if(Boolean.TRUE.equals(overdue)){boolean late=StatsController.overdueAt(row,now);if(!late)return false;}return true;}).toList();}
 @PostMapping("/sub-tasks/{id}/{action:receive|assign|progress|submit|withdraw|extend|transfer}") Object sub(@PathVariable long id,@PathVariable String action,@RequestBody(required=false)Map<String,Object>body,HttpServletRequest q){var b=body==null?new LinkedHashMap<String,Object>():body;var a=policy.actor(q);return writes.run(q,b,()->tasks.subAction(a,id,action,b));}
 @PostMapping("/tasks/{id}/comments") Object comment(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest q){var a=policy.actor(q);return writes.run(q,b,()->tasks.comment(a,id,b));}
 @GetMapping("/collaborations") Object collaborations(HttpServletRequest q){return Api.ok(tasks.collaborations(policy.actor(q)));}
 @PostMapping("/collaborations/{id}/{action:accept|reject}") Object collaboration(@PathVariable long id,@PathVariable String action,@RequestBody(required=false)Map<String,Object>body,HttpServletRequest q){var a=policy.actor(q);var b=body==null?new LinkedHashMap<String,Object>():body;return writes.run(q,b,()->tasks.collaboration(a,id,action,b));}
 @PostMapping("/deadline-requests/{id}/{action:approve|reject}") Object deadline(@PathVariable long id,@PathVariable String action,@RequestBody(required=false)Map<String,Object>body,HttpServletRequest q){var a=policy.actor(q);var b=body==null?new LinkedHashMap<String,Object>():body;return writes.run(q,b,()->tasks.deadline(a,id,action,b));}
 boolean canSeeNotification(Policy.Actor a,Map<String,Object> n){return (Objects.equals(a.company(),Jsons.integer(n.get("companyId")))||a.role().equals("GROUP_LEADER"))&&(n.get("taskId")==null||policy.canSeeTask(a,records.get(Jsons.number(n.get("taskId")))));}
 @GetMapping("/notifications") Object notifications(HttpServletRequest q,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)Boolean read){var a=policy.actor(q);return Api.ok(page(db.notifications(a.uid()).stream().filter(n->canSeeNotification(a,n)).filter(n->read==null||read.equals(n.get("isRead"))).toList(),page,pageSize));}
 @PostMapping("/notifications/{id}/read") Object read(@PathVariable long id,HttpServletRequest q){var a=policy.actor(q);return writes.run(q,Map.of(),()->{var target=db.notifications(a.uid()).stream().filter(n->Jsons.number(n.get("id"))==id).findFirst().orElseThrow(ApiException::denied);if(!(Objects.equals(a.company(),Jsons.integer(target.get("companyId")))||a.role().equals("GROUP_LEADER"))||target.get("taskId")!=null&&!policy.canSeeTask(a,records.get(Jsons.number(target.get("taskId")))))throw ApiException.denied();if(db.readNotification(id,a.uid())!=1)throw ApiException.denied();return Map.of();});}
 @PostMapping("/notifications/archive") Object archive(HttpServletRequest q){var a=policy.actor(q);return writes.run(q,Map.of(),()->{for(var n:db.notifications(a.uid()))if(Boolean.TRUE.equals(n.get("isRead"))&&canSeeNotification(a,n))db.archiveNotification(Jsons.number(n.get("id")),a.uid());return Map.of();});}
 public static Map<String,Object> page(List<?> list,int page,int size){if(page<1||size<1||size>100)throw new ApiException(400,"INVALID_PAGE","分页参数范围错误");int from=(int)Math.min((long)(page-1)*size,list.size());return Records.map("items",list.subList(from,Math.min(from+size,list.size())),"page",page,"pageSize",size,"total",list.size());}
}
